svg.script:
(function(){
  var svg = document.currentScript && document.currentScript.ownerSVGElement;
  if(!svg) return;

  var KEY = "evm_svg_state_v1";
  function load(){
    try{
      var raw = localStorage.getItem(KEY);
      if(raw) return JSON.parse(raw);
    }catch(e){}
    return null;
  }
  function save(state){
    try{ localStorage.setItem(KEY, JSON.stringify(state)); }catch(e){}
  }
  function defaultState(count){
    var c = [];
    for(var i=0;i<count;i++){
      c.push({name:"Candidate "+(i+1), votes:0, icon:null});
    }
    return {locked:false, selected:null, maxCandidates:count, candidates:c};
  }

  function num(v){ return typeof v === "number" ? v : parseFloat(v); }
  function isFiniteNumber(v){ return typeof v === "number" && isFinite(v); }

  function pickLeds(){
    var shapes = Array.prototype.slice.call(svg.querySelectorAll(".st12"));
    var leds = shapes.filter(function(c){
      var cx = num(c.getAttribute("cx"));
      var r = num(c.getAttribute("r"));
      var rx = num(c.getAttribute("rx"));
      var ry = num(c.getAttribute("ry"));
      var sizeOk = (isFiniteNumber(r) && Math.abs(r - 52.4) < 0.5) || (isFiniteNumber(rx) && isFiniteNumber(ry) && Math.abs(rx - 52.4) < 0.5 && Math.abs(ry - 52.4) < 0.5);
      return isFiniteNumber(cx) && sizeOk && Math.abs(cx - 2926.5) < 1;
    });
    leds.sort(function(a,b){ return num(a.getAttribute("cy")) - num(b.getAttribute("cy")); });
    return leds.map(function(el){
      return {el:el, g:el.parentNode, cy:num(el.getAttribute("cy"))};
    });
  }

  function pickButtons(){
    var paths = Array.prototype.slice.call(svg.querySelectorAll("path.st17, path.st18"));
    var items = [];
    for(var i=0;i<paths.length;i++){
      var p = paths[i];
      var bb;
      try{ bb = p.getBBox(); }catch(e){ continue; }
      if(!bb) continue;
      var cx = bb.x + bb.width/2;
      var cy = bb.y + bb.height/2;
      if(cx > 3200 && cx < 3500 && cy > 800 && cy < 4300 && bb.width > 220 && bb.width < 500 && bb.height > 80 && bb.height < 220){
        items.push({el:p, bb:bb, cy:cy});
      }
    }
    items.sort(function(a,b){ return a.cy - b.cy; });
    var rows = [];
    for(var j=0;j<items.length;j++){
      var it = items[j];
      var last = rows.length ? rows[rows.length-1] : null;
      if(!last || Math.abs(it.cy - last.cy) > 60){
        rows.push({cy:it.cy, els:[it.el], bb:{x:it.bb.x,y:it.bb.y,width:it.bb.width,height:it.bb.height}});
      }else{
        last.cy = (last.cy + it.cy) / 2;
        last.els.push(it.el);
        var x1 = Math.min(last.bb.x, it.bb.x);
        var y1 = Math.min(last.bb.y, it.bb.y);
        var x2 = Math.max(last.bb.x + last.bb.width, it.bb.x + it.bb.width);
        var y2 = Math.max(last.bb.y + last.bb.height, it.bb.y + it.bb.height);
        last.bb = {x:x1,y:y1,width:x2-x1,height:y2-y1};
      }
    }
    return rows;
  }

  var leds = pickLeds();
  var buttons = pickButtons();
  var count = Math.min(leds.length, buttons.length);
  if(count <= 0) return;

  var state = load() || defaultState(count);
  if(!state.candidates || !Array.isArray(state.candidates) || state.candidates.length !== count){
    state = defaultState(count);
  }
  for(var si=0; si<count; si++){
    if(!state.candidates[si]) state.candidates[si] = {name:"Candidate "+(si+1), votes:0, icon:null};
    if(typeof state.candidates[si].icon === "undefined") state.candidates[si].icon = null;
  }
  if(!state.maxCandidates || typeof state.maxCandidates !== "number" || !isFinite(state.maxCandidates)){
    state.maxCandidates = count;
  }
  state.maxCandidates = Math.max(1, Math.min(count, Math.floor(state.maxCandidates)));

  var ui = svg.getElementById("evm-ui");
  if(!ui){
    ui = document.createElementNS("http://www.w3.org/2000/svg", "g");
    ui.setAttribute("id","evm-ui");
    svg.appendChild(ui);
  }

  var hitLayer = svg.getElementById("evm-hit");
  if(!hitLayer){
    hitLayer = document.createElementNS("http://www.w3.org/2000/svg", "g");
    hitLayer.setAttribute("id","evm-hit");
    svg.appendChild(hitLayer);
  }

  var adminLayer = svg.getElementById("evm-admin-layer");
  if(!adminLayer){
    adminLayer = document.createElementNS("http://www.w3.org/2000/svg", "g");
    adminLayer.setAttribute("id","evm-admin-layer");
    svg.appendChild(adminLayer);
  }

  function svgEl(tag, attrs){
    var el = document.createElementNS("http://www.w3.org/2000/svg", tag);
    if(attrs){
      for(var k in attrs){
        if(attrs[k] !== null && attrs[k] !== undefined) el.setAttribute(k, String(attrs[k]));
      }
    }
    return el;
  }

  function ensureAdminUI(){
    var hotspot = svg.getElementById("evm-admin-hotspot");
    if(!hotspot){
      hotspot = svgEl("rect",{id:"evm-admin-hotspot",x:0,y:0,width:760,height:760,fill:"transparent","fill-opacity":"0","pointer-events":"all"});
      adminLayer.appendChild(hotspot);
    }

    var admin = svg.getElementById("evm-admin");
    if(!admin){
      admin = svgEl("g",{id:"evm-admin"});
      admin.setAttribute("style","display:none");

      var bg = svgEl("rect",{x:650,y:620,width:3700,height:1180,rx:90,ry:90,class:"evm-admin-bg"});
      admin.appendChild(bg);

      var title = svgEl("text",{x:850,y:790,class:"evm-admin-title","dominant-baseline":"middle","text-anchor":"start"});
      title.textContent = "Admin";
      admin.appendChild(title);

      var sub = svgEl("text",{x:850,y:905,class:"evm-admin-sub","dominant-baseline":"middle","text-anchor":"start"});
      sub.textContent = "Tap a button below";
      admin.appendChild(sub);

      function addBtn(id,label,x,y,cls){
        var g = svgEl("g",{id:id});
        var r = svgEl("rect",{x:x,y:y,width:860,height:210,rx:105,ry:105,class:"evm-admin-btn"+(cls?(" "+cls):"")});
        var t = svgEl("text",{x:x+430,y:y+105,class:"evm-admin-btn-label","dominant-baseline":"middle","text-anchor":"middle"});
        t.textContent = label;
        g.appendChild(r);
        g.appendChild(t);
        admin.appendChild(g);
        return g;
      }

      addBtn("evm-admin-edit","Edit",850,1040,"");
      addBtn("evm-admin-unlock","Unlock",1830,1040,"secondary");
      addBtn("evm-admin-reset","Reset",2810,1040,"danger");
      addBtn("evm-admin-close","Close",850,1310,"secondary");

      adminLayer.appendChild(admin);
    }

    var fab = svg.getElementById("evm-admin-fab");
    if(!fab){
      fab = svgEl("g",{id:"evm-admin-fab"});
      fab.style.cursor = "pointer";
      fab.setAttribute("pointer-events","all");

      var btnX = 420;
      var btnY = 260;
      var btnR = 140;

      var c = svgEl("circle",{cx:btnX,cy:btnY,r:btnR,fill:"#111111","fill-opacity":"0.78"});
      var t = svgEl("text",{x:btnX,y:btnY,"dominant-baseline":"middle","text-anchor":"middle"});
      t.setAttribute("style","font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-weight:900;font-size:120px;fill:#ffffff");
      t.textContent = "⚙";

      var hit = svgEl("circle",{cx:btnX,cy:btnY,r:btnR+40,fill:"transparent","fill-opacity":"0","pointer-events":"all"});

      fab.appendChild(c);
      fab.appendChild(t);
      fab.appendChild(hit);
      adminLayer.appendChild(fab);
    }

    return {hotspot:hotspot, admin:admin};
  }

  function ensureEditorUI(){
    var fo = svg.getElementById("evm-editor-fo");
    if(!fo){
      fo = svgEl("foreignObject",{id:"evm-editor-fo",x:650,y:620,width:3700,height:2400});
      fo.setAttribute("style","display:none");
      fo.setAttribute("pointer-events","all");

      var div = document.createElementNS("http://www.w3.org/1999/xhtml", "div");
      div.setAttribute("id","evm-editor");
      div.setAttribute("style","box-sizing:border-box;width:100%;height:100%;overflow:auto;padding:28px 32px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:rgba(255,255,255,.98);border-radius:90px;border:2px solid rgba(0,0,0,.08)");
      fo.appendChild(div);
      adminLayer.appendChild(fo);
    }
    return fo;
  }

  function editorHide(){
    var fo = svg.getElementById("evm-editor-fo");
    if(fo) fo.style.display = "none";
  }

  function editorShow(){
    var fo = ensureEditorUI();
    fo.style.display = "block";

    var div = fo.querySelector("#evm-editor");
    if(!div) return;

    var html = "";
    html += "<div style='font-weight:900;font-size:42px;color:#111;margin-bottom:10px'>Edit Candidate Names</div>";
    html += "<div style='font-weight:600;font-size:26px;color:#444;margin-bottom:18px'>Set candidate count, change names/icons, then Save.</div>";
    html += "<label style='display:grid;grid-template-columns:260px 1fr;gap:12px;align-items:center;margin:0 0 18px 0'>";
    html += "<span style='font-weight:900;font-size:26px;color:#111'>Candidates</span>";
    html += "<input id='evm-editor-count' type='number' min='1' max='"+count+"' value='"+String(state.maxCandidates || count)+"' style='width:100%;font-size:28px;padding:12px 14px;border-radius:12px;border:1px solid #cfd3da;outline:none' />";
    html += "</label>";
    html += "<div style='display:grid;grid-template-columns:1fr;gap:12px;margin-bottom:18px'>";
    for(var i=0;i<count;i++){
      var v = (state.candidates[i] && state.candidates[i].name) ? state.candidates[i].name : "";
      v = String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');
      html += "<div style='display:grid;grid-template-columns:120px minmax(0,1.6fr) minmax(0,1.4fr);gap:12px;align-items:center'>";
      html += "<span style='font-weight:800;font-size:26px;color:#111'>"+(i+1)+".</span>";
      html += "<input data-idx='"+i+"' value=\""+v+"\" placeholder='Name' style='width:100%;font-size:28px;padding:12px 14px;border-radius:12px;border:1px solid #cfd3da;outline:none' />";
      html += "<label style='font-size:22px;color:#111;display:flex;flex-direction:column;gap:4px'>";
      html += "<span>Icon (PNG/JPG)</span>";
      html += "<input data-idx-icon='"+i+"' type='file' accept='image/png,image/jpeg,image/webp' style='font-size:20px' />";
      html += "</label>";
      html += "</div>";
    }
    html += "</div>";
    html += "<div style='display:flex;gap:12px;flex-wrap:wrap'>";
    html += "<button id='evm-editor-save' style='appearance:none;border:0;border-radius:14px;background:#1777ff;color:#fff;font-weight:900;font-size:28px;padding:14px 18px'>Save</button>";
    html += "<button id='evm-editor-close' style='appearance:none;border:0;border-radius:14px;background:#4b5563;color:#fff;font-weight:900;font-size:28px;padding:14px 18px'>Close</button>";
    html += "</div>";
    div.innerHTML = html;

    var saveBtn = div.querySelector("#evm-editor-save");
    var closeBtn = div.querySelector("#evm-editor-close");
    var iconInputs = div.querySelectorAll("input[data-idx-icon]");
    if(iconInputs && iconInputs.length){
      for(var ii=0; ii<iconInputs.length; ii++){
        (function(inp){
          inp.addEventListener("change", function(){
            var file = inp.files && inp.files[0];
            if(!file) return;
            var idx = parseInt(inp.getAttribute("data-idx-icon"), 10);
            if(!isFinite(idx) || !state.candidates[idx]) return;
            var reader = new FileReader();
            reader.onload = function(ev){
              var data = ev && ev.target ? ev.target.result : null;
              if(!data) return;
              state.candidates[idx].icon = String(data);
              save(state);
              render();
            };
            reader.readAsDataURL(file);
          });
        })(iconInputs[ii]);
      }
    }
    if(saveBtn){
      saveBtn.addEventListener("click", function(){
        var countEl = div.querySelector("#evm-editor-count");
        if(countEl){
          var n = parseInt(String(countEl.value || ""), 10);
          if(isFinite(n)){
            state.maxCandidates = Math.max(1, Math.min(count, n));
          }
        }
        var inputs = div.querySelectorAll("input[data-idx]");
        for(var k=0;k<inputs.length;k++){
          var idx = parseInt(inputs[k].getAttribute("data-idx"),10);
          if(isFinite(idx) && state.candidates[idx]){
            state.candidates[idx].name = String(inputs[k].value || "").trim();
          }
        }
        save(state);
        render();
        editorHide();
      });
    }
    if(closeBtn){
      closeBtn.addEventListener("click", function(){
        editorHide();
      });
    }
  }

  function ensureText(id, cls){
    var t = svg.getElementById(id);
    if(!t){
      t = document.createElementNS("http://www.w3.org/2000/svg", "text");
      t.setAttribute("id", id);
      t.setAttribute("class", cls);
      t.setAttribute("dominant-baseline", "middle");
      t.setAttribute("text-anchor", "start");
      ui.appendChild(t);
    }
    return t;
  }

  function ensureIcon(id){
    var img = svg.getElementById(id);
    if(!img){
      img = document.createElementNS("http://www.w3.org/2000/svg", "image");
      img.setAttribute("id", id);
      img.setAttribute("preserveAspectRatio","xMidYMid meet");
      ui.appendChild(img);
    }
    return img;
  }

  function cleanupOldCovers(){
    for(var i=0;i<count;i++){
      var a = svg.getElementById("evm-serial-cover-"+i);
      if(a && a.parentNode) a.parentNode.removeChild(a);
      var b = svg.getElementById("evm-name-cover-"+i);
      if(b && b.parentNode) b.parentNode.removeChild(b);
    }
  }

  var serialX = 1613;
  var nameX = 1755;
  var iconSlots = null;

  function detectAnchorsAndHidePlaceholders(){
    var candidates = Array.prototype.slice.call(svg.querySelectorAll(".st23"));
    var serialEls = [];
    var nameLineEls = [];
    var nameTextEls = [];
    var blockEls = [];
    var iconEls = [];

    for(var i=0;i<candidates.length;i++){
      var el = candidates[i];
      var bb;
      try{ bb = el.getBBox(); }catch(e){ continue; }
      if(!bb) continue;

      var inList = bb.x > 1450 && bb.x < 2750 && bb.y > 760 && bb.y < 4275;
      if(!inList) continue;

      var isSmallBlock = bb.width < 90 && bb.height < 90 && bb.x < 1750;
      var isSerialLike = bb.width < 220 && bb.height < 140 && bb.x < 1750;
      var isNameLineLike = bb.width > 320 && bb.height <= 50 && bb.x > 1550 && bb.x < 2750;
      var isNameTextLike = bb.width > 240 && bb.height >= 22 && bb.height < 120 && bb.x > 1550 && bb.x < 2750;
      var isIconLike = bb.width > 40 && bb.width < 260 && bb.height > 40 && bb.height < 260 && bb.x > 2250 && bb.x < 2950;

      if(isSmallBlock) blockEls.push({el:el, bb:bb});
      if(isSerialLike) serialEls.push({el:el, bb:bb});
      if(isNameLineLike) nameLineEls.push({el:el, bb:bb});
      if(isNameTextLike) nameTextEls.push({el:el, bb:bb});
      if(isIconLike) iconEls.push({el:el, bb:bb});
    }

    if(serialEls.length){
      serialEls.sort(function(a,b){ return a.bb.y - b.bb.y; });
      var s = serialEls[0].bb;
      serialX = s.x + s.width/2;
    }

    if(nameLineEls.length){
      nameLineEls.sort(function(a,b){ return a.bb.x - b.bb.x; });
      nameX = nameLineEls[0].bb.x + 40;
    }

    iconSlots = null;
    if(iconEls.length){
      iconEls.sort(function(a,b){
        var ay = a.bb.y + a.bb.height/2;
        var by = b.bb.y + b.bb.height/2;
        return ay - by;
      });
      var picked = iconEls.slice(0, count);
      if(picked.length === count){
        iconSlots = picked.map(function(it){ return it.bb; });
      }
    }

    var toHide = [];
    for(var j=0;j<blockEls.length;j++) toHide.push(blockEls[j].el);
    for(var k=0;k<serialEls.length;k++) toHide.push(serialEls[k].el);
    for(var m=0;m<nameLineEls.length;m++) toHide.push(nameLineEls[m].el);
    for(var n=0;n<nameTextEls.length;n++) toHide.push(nameTextEls[n].el);
    for(var q=0;q<iconEls.length;q++) toHide.push(iconEls[q].el);

    for(var t=0;t<toHide.length;t++){
      toHide[t].style.display = "none";
    }
  }

  function render(){
    var maxN = Math.max(1, Math.min(count, Math.floor(state.maxCandidates || count)));
    for(var i=0;i<count;i++){
      var cy = leds[i].cy;
      var serial = ensureText("evm-serial-"+i, "evm-serial");
      var name = ensureText("evm-name-"+i, "evm-name");
      var iconImg = ensureIcon("evm-icon-"+i);

      serial.setAttribute("x", String(serialX));
      serial.setAttribute("y", String(cy));
      serial.setAttribute("text-anchor", "middle");

      name.setAttribute("x", String(nameX));
      name.setAttribute("y", String(cy));

      var slot = iconSlots && iconSlots[i] ? iconSlots[i] : null;
      if(slot){
        var pad = 6;
        var w = Math.max(1, slot.width - pad*2);
        var h = Math.max(1, slot.height - pad*2);
        iconImg.setAttribute("x", String(slot.x + pad));
        iconImg.setAttribute("y", String(slot.y + pad));
        iconImg.setAttribute("width", String(w));
        iconImg.setAttribute("height", String(h));
      }else{
        var iconW = 260;
        var iconH = 200;
        var iconCx = leds[i].el ? num(leds[i].el.getAttribute("cx")) - 430 : (nameX + 260);
        var iconX = iconCx - iconW/2;
        var iconY = cy - iconH/2;
        iconImg.setAttribute("x", String(iconX));
        iconImg.setAttribute("y", String(iconY));
        iconImg.setAttribute("width", String(iconW));
        iconImg.setAttribute("height", String(iconH));
      }

      var active = i < maxN;
      serial.style.display = active ? "inline" : "none";
      name.style.display = active ? "inline" : "none";
      iconImg.style.display = active && state.candidates[i].icon ? "inline" : "none";

      if(active){
        serial.textContent = String(i + 1);
        name.textContent = (state.candidates[i].name || "").trim();
        if(state.candidates[i].icon){
          try{
            iconImg.setAttributeNS("http://www.w3.org/1999/xlink","href", state.candidates[i].icon);
          }catch(e){
            iconImg.setAttribute("href", state.candidates[i].icon);
          }
        }
      }else{
        serial.textContent = "";
        name.textContent = "";
        try{ iconImg.removeAttributeNS("http://www.w3.org/1999/xlink","href"); }catch(e){}
        iconImg.removeAttribute("href");
      }
    }

    for(var j=0;j<count;j++){
      if(leds[j].g && leds[j].g.classList) leds[j].g.classList.remove("evm-led-on","evm-led-blink");
    }
    if(state.selected !== null && state.selected >= 0 && state.selected < count){
      if(leds[state.selected].g && leds[state.selected].g.classList) leds[state.selected].g.classList.add("evm-led-on");
    }
  }

  function blinkLed(index){
    if(leds[index].g && leds[index].g.classList) leds[index].g.classList.add("evm-led-on","evm-led-blink");
    setTimeout(function(){
      if(leds[index].g && leds[index].g.classList) leds[index].g.classList.remove("evm-led-blink");
    }, 1200);
  }

  function vote(index){
    if(state.locked) return;
    if(index >= Math.max(1, Math.min(count, Math.floor(state.maxCandidates || count)))) return;
    state.locked = true;
    state.selected = index;
    state.candidates[index].votes = (state.candidates[index].votes || 0) + 1;
    save(state);
    render();
    blinkLed(index);
  }

  function installHitTargets(){
    for(var i=0;i<count;i++){
      var id = "evm-hit-"+i;
      var hit = svg.getElementById(id);
      if(!hit){
        hit = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        hit.setAttribute("id", id);
        hit.setAttribute("rx", "40");
        hit.setAttribute("ry", "40");
        hit.setAttribute("style","fill:transparent;pointer-events:all");
        hitLayer.appendChild(hit);
      }
      var bb = buttons[i].bb;
      var pad = 18;
      hit.setAttribute("x", String(bb.x - pad));
      hit.setAttribute("y", String(bb.y - pad));
      hit.setAttribute("width", String(bb.width + pad*2));
      hit.setAttribute("height", String(bb.height + pad*2));

      for(var k=0;k<buttons[i].els.length;k++){
        buttons[i].els[k].style.pointerEvents = "none";
      }

      (function(idx, el){
        el.addEventListener("click", function(ev){
          ev.preventDefault();
          ev.stopPropagation();
          vote(idx);
        }, false);
        el.addEventListener("touchstart", function(ev){
          if(ev.cancelable) ev.preventDefault();
          vote(idx);
        }, {passive:false});
      })(i, hit);
    }
  }

  function clientToSvg(ev){
    var r = svg.getBoundingClientRect();
    var vb = svg.viewBox && svg.viewBox.baseVal;
    if(!vb) return null;
    var x = (ev.clientX - r.left) / r.width * vb.width + vb.x;
    var y = (ev.clientY - r.top) / r.height * vb.height + vb.y;
    return {x:x,y:y};
  }

  function adminShow(){
    var uiParts = ensureAdminUI();
    uiParts.admin.style.display = "inline";
  }
  function adminHide(){
    var admin = svg.getElementById("evm-admin");
    if(admin) admin.style.display = "none";
    editorHide();
  }

  function wireAdminButtons(){
    ensureAdminUI();
    var btnEdit = svg.getElementById("evm-admin-edit");
    var btnUnlock = svg.getElementById("evm-admin-unlock");
    var btnReset = svg.getElementById("evm-admin-reset");
    var btnClose = svg.getElementById("evm-admin-close");

    function onTap(el, fn){
      if(!el) return;
      el.style.cursor = "pointer";
      el.addEventListener("click", function(ev){
        ev.preventDefault();
        ev.stopPropagation();
        fn();
      }, false);
      el.addEventListener("touchstart", function(ev){
        if(ev.cancelable) ev.preventDefault();
      }, {passive:false});
    }

    onTap(btnEdit, function(){ editorShow(); });
    onTap(btnUnlock, function(){
      state.locked = false;
      state.selected = null;
      save(state);
      render();
      adminHide();
    });
    onTap(btnReset, function(){
      try{ localStorage.removeItem(KEY); }catch(e){}
      state = defaultState(count);
      save(state);
      render();
      adminHide();
    });
    onTap(btnClose, function(){ adminHide(); });
  }

  function getClientPoint(ev){
    if(ev && ev.touches && ev.touches.length) return {clientX:ev.touches[0].clientX, clientY:ev.touches[0].clientY};
    if(ev && ev.changedTouches && ev.changedTouches.length) return {clientX:ev.changedTouches[0].clientX, clientY:ev.changedTouches[0].clientY};
    return {clientX:ev.clientX, clientY:ev.clientY};
  }

  var pressTimer = null;
  var pressStart = null;
  function clearPress(){
    if(pressTimer){ clearTimeout(pressTimer); pressTimer = null; }
    pressStart = null;
  }

  function startPress(ev){
    var p = getClientPoint(ev);
    pressStart = {x:p.clientX, y:p.clientY};
    clearTimeout(pressTimer);
    pressTimer = setTimeout(function(){
      pressTimer = null;
      adminShow();
    }, 650);
  }

  function movePress(ev){
    if(!pressStart) return;
    var p = getClientPoint(ev);
    var dx = p.clientX - pressStart.x;
    var dy = p.clientY - pressStart.y;
    if((dx*dx + dy*dy) > 14*14) clearPress();
  }

  function endPress(){ clearPress(); }

  var parts = ensureAdminUI();
  wireAdminButtons();

  cleanupOldCovers();
  detectAnchorsAndHidePlaceholders();

  var fabBtn = svg.getElementById("evm-admin-fab");
  if(fabBtn){
    fabBtn.addEventListener("click", function(ev){
      ev.preventDefault();
      ev.stopPropagation();
      adminShow();
      editorShow();
    }, false);
    fabBtn.addEventListener("touchstart", function(ev){
      if(ev.cancelable) ev.preventDefault();
      adminShow();
      editorShow();
    }, {passive:false});
  }

  parts.hotspot.addEventListener("pointerdown", function(ev){
    if(ev.pointerType === "mouse" && ev.button !== 0) return;
    ev.preventDefault();
    ev.stopPropagation();
    startPress(ev);
  }, false);
  parts.hotspot.addEventListener("pointermove", function(ev){
    movePress(ev);
  }, false);
  parts.hotspot.addEventListener("pointerup", function(ev){
    endPress();
  }, false);
  parts.hotspot.addEventListener("pointercancel", function(ev){
    endPress();
  }, false);

  parts.hotspot.addEventListener("touchstart", function(ev){
    if(ev.cancelable) ev.preventDefault();
    startPress(ev);
  }, {passive:false});
  parts.hotspot.addEventListener("touchmove", function(ev){
    movePress(ev);
  }, {passive:true});
  parts.hotspot.addEventListener("touchend", function(ev){
    endPress();
  }, {passive:true});
  parts.hotspot.addEventListener("touchcancel", function(ev){
    endPress();
  }, {passive:true});

  installHitTargets();
  render();
})();
